import{_ as d,C as r,o as p,c as h,j as a,a as t,G as n,a2 as s}from"./chunks/framework.BgSoyxN5.js";const v=JSON.parse('{"title":"What TickerForge Gives A Partner | Access, Content, Tracking, Referral Rewards","description":"The other half of the partner exchange: the product access, the ready-to-post content, the tracked links, the numbers we report back, and how referral rewards are calculated and paid.","frontmatter":{"title":"What TickerForge Gives A Partner | Access, Content, Tracking, Referral Rewards","description":"The other half of the partner exchange: the product access, the ready-to-post content, the tracked links, the numbers we report back, and how referral rewards are calculated and paid.","aside":false,"locale":"en","alternateLocales":{"en":"/partners/what-you-get","ru":"/ru/partners/what-you-get"},"pageClass":"partners-page"},"headers":[],"relativePath":"partners/what-you-get.md","filePath":"partners/what-you-get.md","lastUpdated":1788362384000}'),c={name:"partners/what-you-get.md"},u={class:"partners-wide"};function g(m,e,f,w,y,b){const o=r("PartnerPageAnalytics"),i=r("PartnerReferralCta"),l=r("PartnerLeadForm");return p(),h("div",null,[e[0]||(e[0]=a("h1",{id:"what-we-give-a-partner",tabindex:"-1"},[t("What We Give A Partner "),a("a",{class:"header-anchor",href:"#what-we-give-a-partner","aria-label":'Permalink to "What We Give A Partner"'},"​")],-1)),e[1]||(e[1]=a("p",null,[a("a",{href:"/partners/requirements"},"Partner Requirements"),t(" states what we ask of a partner. This page states the other half: what TickerForge commits to giving in return, in the same plain terms.")],-1)),e[2]||(e[2]=a("p",null,"Nothing here is conditional on results. Everything below starts the day a pilot is approved and runs for the whole pilot window.",-1)),n(o,{offer:"what_you_get",locale:"en"}),e[3]||(e[3]=s('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#apply" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="partner_hero">Apply For A Pilot</a><a class="partners-button partners-button--secondary" href="#rewards" data-partner-event="cta" data-partner-option="rewards" data-analytics-placement="partner_hero">How Rewards Work</a></div><p class="partners-locale-switch"><a href="/ru/partners/what-you-get" hreflang="ru" data-partner-event="cta" data-partner-option="locale_ru" data-analytics-placement="partner_locale_switch">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/partners">Back to all partner options</a> · <a href="/partners/requirements">Partner requirements</a> · <a href="/partners/cabinet">Partner Cabinet</a> · <a href="/partners/stock-analysis-and-ideas">Telegram research</a> · <a href="/partners/market-news">Market news</a></p><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="access" tabindex="-1">⭐ Standard Access For The Whole Pilot <a class="header-anchor" href="#access" aria-label="Permalink to &quot;⭐ Standard Access For The Whole Pilot {#access}&quot;">​</a></h2><p>An approved pilot switches your own TickerForge account to Standard for the length of the pilot window. That is what makes partner posts worth publishing: they are built from the full research layer, not from the free public preview.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Screeners without the free ceiling.</strong> The TickerForge score range opens up instead of stopping at the public cut-off.</li><li><strong>Higher Smart Alerts and tracking limits.</strong> More tracked companies, more alert subscriptions.</li><li><strong>Standard-level portfolio reports and diagnostics.</strong></li><li><strong>Workspace on the website shows <em>Partner pilot</em></strong> instead of Free, so the whole product behaves consistently across bot and site.</li></ul></div><p>Access is granted by approval, not by payment. It is not a purchase, it does not make you a paying subscriber in our reports, and it does not consume an Early Access slot.</p><h2 id="content" tabindex="-1">🧠 Content You Can Publish The Same Day <a class="header-anchor" href="#content" aria-label="Permalink to &quot;🧠 Content You Can Publish The Same Day {#content}&quot;">​</a></h2><p>Every partner direction has a list of formats that are live in the Partner Cabinet today, and a list of formats available on request for a pilot. The three program pages carry the current lists:</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format partners-format--linked"><span>Program</span><strong><a href="/partners/stock-analysis-and-ideas">Stock Analysis &amp; Ideas</a></strong><p>Company research: Stock Verdict, Insider Activity, Fund Moves, and the weekly rubric ideas.</p></div><div class="partners-format partners-format--linked"><span>Program</span><strong><a href="/partners/market-news">Market News</a></strong><p>Recurring market and macro context: Market Regime, its state-change alert, and U.S. Economic Health.</p></div><div class="partners-format partners-format--linked"><span>Program</span><strong><a href="/partners/portfolio-health">Portfolio Health</a></strong><p>Portfolio diagnostics content, scoped per pilot rather than generated with one tap.</p></div></div></div><p>What we commit to about that content:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Real data, generated on demand.</strong> A post is the live product screen at the moment you press the button, not a template with your ticker dropped into it.</li><li><strong>The same post the channel publishes.</strong> Formatting and the channel image included, so it can be forwarded as it arrives.</li><li><strong>Honest refusals.</strong> When the underlying research is not there, the Cabinet says so and generates nothing. The state-change alert, for one, only exists on the weeks the market regime actually turned — you will never be handed a post announcing a change that did not happen.</li><li><strong>One rubric idea per week is reserved for you</strong>, so two partners are not handed the same company on the same week.</li></ul></div><h2 id="language" tabindex="-1">🌐 Posts In Your Audience&#39;s Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;🌐 Posts In Your Audience&#39;s Language {#language}&quot;">​</a></h2><p>The Partner Cabinet has an English / Russian switch under <strong>Generate Post</strong>. It changes the whole post, not just the button under it, and it applies to every format. Your Cabinet stays in English either way — the setting is about what your readers get.</p><h2 id="tracking" tabindex="-1">🔗 Tracked Links And Attribution <a class="header-anchor" href="#tracking" aria-label="Permalink to &quot;🔗 Tracked Links And Attribution {#tracking}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Every generated post carries your own tracked link</strong>, already inside the post&#39;s call to action. There is nothing to paste, and nothing to configure.</li><li><strong>The link opens the bot, not a redirect page.</strong> A reader lands directly on the matching TickerForge workflow — the stock card, the market dashboard, the US Economy menu.</li><li><strong>A personal referral code and link</strong> are issued automatically when your pilot is approved. That is a second, separate link for a bio, a story, or a comment — generated posts attribute readers on their own, without it.</li><li><strong>Attribution is first-touch.</strong> The reader who arrives through your post is bound to you, and stays bound.</li></ul></div><h2 id="rewards" tabindex="-1">💰 Referral Rewards <a class="header-anchor" href="#rewards" aria-label="Permalink to &quot;💰 Referral Rewards {#rewards}&quot;">​</a></h2><p>Readers attributed through your partner links join the existing TickerForge referral program and earn under exactly the same rules as <a href="/ambassador">/ambassador</a> — the partner program does not invent a separate rate.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>20% of a referred user&#39;s subscription, every month</strong>, for as long as that subscription stays active. There is no cap on referrals or on monthly rewards.</li><li><strong>Calculated per calendar month</strong> from the paid plans your referred users held during that month.</li><li><strong>Charged in Telegram Stars.</strong> Plans are priced in Stars; the USD figures on the <a href="/pricing">pricing page</a> are references, not a second price list.</li><li><strong>Visible before it is paid.</strong> <em>My Monthly Earnings</em> in the bot is a live estimate from current subscription state — a working number, not a settled invoice.</li><li><strong>Payout details are agreed individually</strong> once you have your first paying referrals. Ask through the bot or <a href="/contact">contact us</a> if you want the terms confirmed before you start.</li></ul></div><p class="partners-fineprint">Rewards depend on how many referred users hold an active paid plan in a given month. Nothing here is a forecast of what a channel will earn.</p><h2 id="reporting" tabindex="-1">📊 The Numbers We Report Back <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;📊 The Numbers We Report Back {#reporting}&quot;">​</a></h2><p>A pilot is only worth running if both sides can see whether it worked. Inside the Partner Cabinet:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Statistics</strong> — referred users, active paying referrals this month, estimated monthly payout, and a breakdown per post type.</li><li><strong>Bot starts per post type</strong> — how many readers actually opened TickerForge from each kind of post, so you can see which format your audience responds to.</li><li><strong>Monthly report</strong> — the current or previous month as an XLSX snapshot, generated on request.</li><li><strong>My Progress</strong> — status, access window, generated posts and verified posts.</li></ul></div><h2 id="not-included" tabindex="-1">What Is Not Included <a class="header-anchor" href="#not-included" aria-label="Permalink to &quot;What Is Not Included {#not-included}&quot;">​</a></h2><p>An approved pilot grants Standard access and nothing beyond it. Pro-level access, bulk API or raw data feeds, custom or white-label reports, co-branded landing pages, paid placements, and category exclusivity are separate commercial discussions — all of them easier to justify once a first pilot has real numbers behind it. The full list is on <a href="/partners/requirements#not-included">Partner Requirements</a>.</p>',26)),n(i),e[4]||(e[4]=a("h2",{id:"apply",tabindex:"-1"},[t("Apply For A Partner Pilot "),a("a",{class:"header-anchor",href:"#apply","aria-label":'Permalink to "Apply For A Partner Pilot {#apply}"'},"​")],-1)),e[5]||(e[5]=a("p",null,"Tell us about the channel and the pilot you want to run: channel or community link, audience size and typical post reach, language, main topic, which partner direction you want, and your first post idea.",-1)),a("div",u,[n(l,{source:"partners_what_you_get"})]),e[6]||(e[6]=s('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/partners">All partner options</a></li><li><a href="/partners/requirements">Partner requirements — what we ask</a></li><li><a href="/partners/cabinet">How Partner Cabinet works</a></li><li><a href="/partners/stock-analysis-and-ideas">Telegram research partners</a></li><li><a href="/partners/market-news">Market news partners</a></li><li><a href="/partners/portfolio-health">Portfolio health partners</a></li><li><a href="/ambassador">Ambassador / referral program</a></li><li><a href="/pricing">TickerForge Pricing</a></li></ul>',2))])}const P=d(c,[["render",g]]);export{v as __pageData,P as default};
